insert into public.categories (slug, name, description, color, icon, is_premium, sort_order) values
  ('locations', 'Locations', 'Notable places and landmarks.', '#E6EAF0', 'map-pin', false, 10),
  ('collectibles', 'Collectibles', 'Items to find and track.', '#5CF28B', 'gem', false, 20),
  ('missions', 'Missions', 'Mission start points.', '#FF8A3D', 'flag', false, 30),
  ('easter-eggs', 'Easter Eggs', 'Secrets and references.', '#C9A7FF', 'sparkles', false, 40),
  ('businesses', 'Businesses', 'Shops and services.', '#62C6F2', 'store', false, 50),
  ('properties', 'Properties', 'Purchasable properties.', '#F2C94C', 'home', false, 60),
  ('vehicles', 'Vehicles', 'Vehicle spawn locations.', '#F2665C', 'car', false, 70),
  ('hidden', 'Hidden Discoveries', 'Rare and hidden finds. Premium only.', '#9AA4FF', 'eye-off', true, 80)
on conflict (slug) do nothing;

